/**
 * Service Types — Sawaa Dashboard
 *
 * Response shapes are DERIVED from the committed OpenAPI snapshot
 * (`lib/types/api.generated.ts`, regenerated by `pnpm openapi:sync`), so a
 * backend response change is a type error here instead of a silent runtime
 * mismatch. Request payloads, query params and UI value objects stay local and
 * are marked as such.
 */

import type { components } from "@/lib/types/api.generated"
import type { PaginatedQuery } from "./common"

type Schemas = components["schemas"]

/** Wire vocabulary for the delivery channel (Prisma enum as the API sends it). */
export type ServiceDeliveryType = Schemas["DeliveryType"]

/* ─── Entities (derived from OpenAPI) ─── */

/** The category row on GET/PATCH categories (`CategoryResponseDto`). */
type CategoryWire = Schemas["CategoryResponseDto"]
/** A category list row: the same fields plus `department` and `_count`. */
type CategoryListWire = Schemas["CategoryListItemResponseDto"]
/**
 * The owning department as each endpoint embeds it: the categories list sends
 * id/nameAr/nameEn, while the services list sends the whole department row
 * (`ServiceEmbeddedCategoryListItemDto`). The union keeps the dashboard honest
 * about both and exposes exactly the fields it reads.
 */
export type ServiceCategoryDepartment =
  | CategoryListWire["department"]
  | NonNullable<Schemas["ServiceEmbeddedCategoryListItemDto"]["department"]>

/**
 * Dashboard-facing category. List endpoints include `department` and `_count`;
 * GET/PATCH by id and the embedded service category do not, so both are
 * optional. Everything else is on every response.
 */
export type ServiceCategory = CategoryWire & {
  department?: ServiceCategoryDepartment | null
  _count?: CategoryListWire["_count"]
}

/** The full service payload (`ServiceDetailResponseDto`) used by GET/POST/PATCH. */
type ServiceWire = Schemas["ServiceDetailResponseDto"]
/**
 * Dashboard-facing service.
 *
 * Every service response carries the raw row, its category and its duration
 * options. `employeeCount` is only computed by the list endpoint (the detail,
 * create, update and restore payloads have no count), so it stays optional.
 *
 * `price` and `depositAmount` are decimal strings on the wire (Prisma Decimal
 * serializes through `toJSON`); every reader passes them through `Number(...)`
 * or the money helpers, which is unchanged.
 */
export type Service = Omit<ServiceWire, "category"> & {
  category: ServiceCategory | null
  /** Active employees offering this service; only GET /services computes it. */
  employeeCount?: number
}

/** A delivery-type booking config plus its duration options and windows. */
export type ServiceBookingType = Schemas["ServiceBookingConfigResponseDto"]

/** A stored duration option (service-level or practitioner-owned). */
export type ServiceDurationOption = Schemas["ServiceDurationOptionRecordDto"]

/** A custom availability window for one delivery type. */
export type ServiceAvailabilityWindow = Schemas["ServiceAvailabilityWindowRecordDto"]

/* ─── Service employees ─── */

/**
 * An effective duration row.
 *
 * The snapshot documents `deliveryType` as a plain string because
 * `resolveEffectiveDurations` maps it with `String(row.deliveryType)`; the
 * column is the Prisma `DeliveryType` enum, so the value is always IN_PERSON or
 * ONLINE. The dashboard narrows to that union once, here (same pattern as
 * `specialty` in `lib/types/employee.ts`), and the contract test pins it.
 */
export type PractitionerDurationItem = Omit<
  Schemas["EmployeeEffectiveDurationDto"],
  "deliveryType"
> & { deliveryType: ServiceDeliveryType }

/** Durations for one delivery type, as returned by the practitioner endpoints. */
export type PractitionerDurationGroup = Omit<
  Schemas["EmployeeEffectiveDurationGroupDto"],
  "deliveryType" | "durations"
> & {
  deliveryType: ServiceDeliveryType
  durations: PractitionerDurationItem[]
}

/** One bookable delivery type for a practitioner (effective price/duration). */
export type ServiceEmployeeServiceType = Schemas["ServiceEmployeeServiceTypeDto"]

/**
 * A practitioner offering the service, with their bookable delivery types.
 *
 * `effectiveDurations[].deliveryType` is narrowed from the wire `string` to the
 * `DeliveryType` union (see `PractitionerDurationItem`); nothing else changes.
 */
export type ServiceEmployee = Omit<
  Schemas["ServiceEmployeeAssignmentDto"],
  "effectiveDurations"
> & { effectiveDurations: PractitionerDurationGroup[] }

/* ─── Query (local; request params, not response shapes) ─── */

export interface ServiceListQuery extends PaginatedQuery {
  branchId?: string
  departmentId?: string
  sortBy?: "createdAt" | "nameAr" | "nameEn" | "price" | "durationMins" | "isActive"
  sortOrder?: "asc" | "desc"
  historicalContext?: boolean
  categoryId?: string
  isActive?: boolean
  includeHidden?: boolean
  includeArchived?: boolean
  search?: string
}

export interface CategoryListQuery extends PaginatedQuery {
  search?: string
  isActive?: boolean
  departmentId?: string
}
